              {'id': 'PASSAGES:collects-epistles-gospels/epiphany-6.md:9:1',
               'file': 'collects-epistles-gospels/epiphany-6.md',
               'line': 9,
               'anchor': 'O God, the strength of all who put',
               'old': 'Amen.',
               'new': 'Amen.\n'
                      '\n'
                      '## The Collect (Contemporary)\n'
                      '\n'
                      'O God, the strength of all who put their trust in you: Mercifully accept '
                      'our prayers; and because in our weakness we can do nothing good without '
                      'you, give us the help of your grace, that in keeping your commandments we '
                      'may please you both in will and deed; through Jesus Christ our Lord, who '
                      'lives and reigns with you and the Holy Spirit, one God, for ever and ever. '
                      'Amen.',
               'class': 'b',
               'page': 216,
               'closes': 'Sixth Sunday after the Epiphany',
               'collect': 'cont'},
